INSERT INTO `destination` VALUES (4,'Paris','citta','The City of Light, offering world-class art, fashion, and the iconic Eiffel Tower.','https://images.unsplash.com/photo-1550340499-a6c60fc8287c?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8UGFyaXMlMjBjaXR5JTIwbGFuZHNjYXBlfGVufDB8MHx8fDE3ODk5MzMzNDd8MA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:46:45','CDG'),(5,'London','citta','A vibrant metropolis blending historic landmarks like Big Ben with cutting-edge culture.','https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8TG9uZG9uJTIwY2l0eSUyMGxhbmRzY2FwZXxlbnwwfDB8fHwxNzg5OTMzMzQ5fDA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:46:48','LHR'),(6,'Bangkok','citta','A bustling capital known for ornate shrines, vibrant street life, and floating markets.','https://images.unsplash.com/photo-1547640084-1dfcc7ef3b22?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8QmFuZ2tvayUyMGNpdHklMjBsYW5kc2NhcGV8ZW58MHwwfHx8MTc4OTkzMzM1Mnww&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:46:50','BKK'),(7,'Dubai','citta','A futuristic oasis of luxury shopping, ultramodern architecture, and a lively nightlife.','https://images.unsplash.com/photo-1512453979798-5ea266f8880c?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8RHViYWklMjBjaXR5JTIwbGFuZHNjYXBlfGVufDB8MHx8fDE3ODk5MzMzNTV8MA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:46:52','DXB'),(8,'New York','citta','The city that never sleeps, featuring Times Square, Broadway, and a diverse culinary scene.','https://images.unsplash.com/photo-1496588152823-86ff7695e68f?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8TmV3JTIwWW9yayUyMGNpdHklMjBsYW5kc2NhcGV8ZW58MHwwfHx8MTc4OTkzMzM1N3ww&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:46:55','JFK'),(9,'Rome','citta','The Eternal City, home to ancient ruins like the Colosseum and incredible Italian cuisine.','https://images.unsplash.com/photo-1555992828-35627f3b373f?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8Um9tZSUyMGNpdHklMjBsYW5kc2NhcGV8ZW58MHwwfHx8MTc4OTkzMzM2MHww&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:46:57','FCO'),(10,'Tokyo','citta','A dazzling mix of neon-lit skyscrapers, historic temples, and exquisite gastronomy.','https://images.unsplash.com/photo-1513407030348-c983a97b98d8?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8VG9reW8lMjBjaXR5JTIwbGFuZHNjYXBlfGVufDB8MHx8fDE3ODk5MzMzNjJ8MA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:47:00','HND'),(11,'Istanbul','citta','Where East meets West, famous for the Hagia Sophia and the bustling Grand Bazaar.','https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8SXN0YW5idWwlMjBjaXR5JTIwbGFuZHNjYXBlfGVufDB8MHx8fDE3ODk5MzMzNjV8MA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:47:03','IST'),(12,'Seoul','citta','A dynamic tech hub that perfectly preserves its ancient palaces and traditional street food.','https://images.unsplash.com/photo-1554310603-d39d43033735?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8U2VvdWwlMjBjaXR5JTIwbGFuZHNjYXBlfGVufDB8MHx8fDE3ODk5MzMzNjh8MA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:47:06','ICN'),(13,'Barcelona','mare','A vibrant coastal city famed for Gaudí\'s surreal architecture and sun-drenched beaches.','https://images.unsplash.com/photo-1688680437050-d2cddf4f20b2?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8QmFyY2Vsb25hJTIwY2l0eSUyMGxhbmRzY2FwZXxlbnwwfDB8fHwxNzg5OTMzMzcxfDA&ixlib=rb-4.1.0&q=80&w=1080','2026-08-31 13:47:08','BCN'),(14,'Bali','mare','A tropical paradise of forested volcanic mountains, iconic rice paddies, and coral reefs.','https://images.unsplash.com/photo-1711609110590-5ad5c4599e56?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3wxMDUwMjE5fDB8MXxzZWFyY2h8MXx8QmFsaSUyMGNpdHklMjB